class Solution:
    def minimumCost(self, n: int, prices: List[int], roads: List[List[int]]) -> List[int]:
        INF = float('inf')
        A = [[INF] * n for _ in range(n)]
        B = [[INF] * n for _ in range(n)]
        for i in range(n):
            A[i][i] = B[i][i] = 0
        for u, v, c, t in roads:
            A[u][v] = A[v][u] = min(A[u][v], c)
            B[u][v] = B[v][u] = min(B[v][u], c * t)
        for k in range(n):
            Ak, Bk = A[k], B[k]
            for i in range(n):
                aik, bik = A[i][k], B[i][k]
                Ai, Bi = A[i], B[i]
                for j in range(n):
                    if aik + Ak[j] < Ai[j]:
                        Ai[j] = aik + Ak[j]
                    if bik + Bk[j] < Bi[j]:
                        Bi[j] = bik + Bk[j]
        return [min(A[i][j] + prices[j] + B[i][j] for j in range(n)) for i in range(n)]

