import heapq

class Solution:
    def minimumCost(self, n: int, prices: List[int], roads: List[List[int]]) -> List[int]:
        g1 = [[] for _ in range(n)]
        g2 = [[] for _ in range(n)]
        for u, v, c, t in roads:
            g1[u].append((v, c)); g1[v].append((u, c))
            g2[u].append((v, c * t)); g2[v].append((u, c * t))

        def dijkstra(g, s):
            dist = [float('inf')] * n
            dist[s] = 0
            h = [(0, s)]
            while h:
                d, u = heapq.heappop(h)
                if d > dist[u]:
                    continue
                for v, w in g[u]:
                    nd = d + w
                    if nd < dist[v]:
                        dist[v] = nd
                        heapq.heappush(h, (nd, v))
            return dist

        D1 = [dijkstra(g1, i) for i in range(n)]
        D2 = [dijkstra(g2, i) for i in range(n)]
        return [min(D1[i][j] + prices[j] + D2[i][j] for j in range(n)) for i in range(n)]

