    vector<long long> minimumCost(int n, vector<int>& prices, vector<vector<int>>& roads) {
        vector<vector<pair<int,long long>>> g1(n), g2(n);
        for (auto& r : roads) {
            int u = r[0], v = r[1]; long long c = r[2], t = r[3];
            g1[u].push_back({v, c}); g1[v].push_back({u, c});
            g2[u].push_back({v, c * t}); g2[v].push_back({u, c * t});
        }
        auto dijkstra = [&](vector<vector<pair<int,long long>>>& g, int s) {
            vector<long long> dist(n, LLONG_MAX);
            priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;
            dist[s] = 0; pq.push({0, s});
            while (!pq.empty()) {
                auto [d, u] = pq.top(); pq.pop();
                if (d > dist[u]) continue;
                for (auto [v, w] : g[u])
                    if (d + w < dist[v]) { dist[v] = d + w; pq.push({dist[v], v}); }
            }
            return dist;
        };
        vector<vector<long long>> D1(n), D2(n);
        for (int i = 0; i < n; i++) { D1[i] = dijkstra(g1, i); D2[i] = dijkstra(g2, i); }
