class Solution {
    public int[] minimumCost(int n, int[] prices, int[][] roads) {
        List<List<long[]>> g1 = new ArrayList<>(), g2 = new ArrayList<>();
        for (int i = 0; i < n; i++) { g1.add(new ArrayList<>()); g2.add(new ArrayList<>()); }
        for (int[] r : roads) {
            int u = r[0], v = r[1]; long c = r[2], t = r[3];
            g1.get(u).add(new long[]{v, c}); g1.get(v).add(new long[]{u, c});
            g2.get(u).add(new long[]{v, c * t}); g2.get(v).add(new long[]{u, c * t});
        }
        java.util.function.BiFunction<List<List<long[]>>, Integer, long[]> dij = (g, s) -> {
            long[] dist = new long[n];
            java.util.Arrays.fill(dist, Long.MAX_VALUE);
            PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
            dist[s] = 0; pq.add(new long[]{0, s});
            while (!pq.isEmpty()) {
                long[] top = pq.poll();
                long d = top[0]; int u = (int) top[1];
                if (d > dist[u]) continue;
                for (long[] e : g.get(u)) {
                    int v = (int) e[0]; long nd = d + e[1];
                    if (nd < dist[v]) { dist[v] = nd; pq.add(new long[]{nd, v}); }
                }
            }
            return dist;
        };
        long[][] D1 = new long[n][], D2 = new long[n][];
        for (int i = 0; i < n; i++) { D1[i] = dij.apply(g1, i); D2[i] = dij.apply(g2, i); }
        int[] ans = new int[n];
        for (int i = 0; i < n; i++) {
            long best = Long.MAX_VALUE;
            for (int j = 0; j < n; j++)
                best = Math.min(best, D1[i][j] + prices[j] + D2[i][j]);
            ans[i] = (int) best;
        }
        return ans;
    }
}

