var minimumCost = function(n, prices, roads) {
    const g1 = Array.from({length: n}, () => []);
    const g2 = Array.from({length: n}, () => []);
    for (const [u, v, c, t] of roads) {
        g1[u].push([v, c]); g1[v].push([u, c]);
        g2[u].push([v, c * t]); g2[v].push([u, c * t]);
    }
    const dijkstra = (g, s) => {
        const dist = Array(n).fill(Infinity);
        dist[s] = 0;
        const h = [[0, s]];
        const push = (x) => { h.push(x); let i = h.length - 1;
            while (i > 0) { const p = (i - 1) >> 1; if (h[p][0] <= h[i][0]) break;
                [h[p], h[i]] = [h[i], h[p]]; i = p; } };
        const pop = () => { const top = h[0], last = h.pop();
            if (h.length) { h[0] = last; let i = 0;
                for (;;) { let l = 2*i+1, r = l+1, m = i;
                    if (l < h.length && h[l][0] < h[m][0]) m = l;
                    if (r < h.length && h[r][0] < h[m][0]) m = r;
                    if (m === i) break; [h[m], h[i]] = [h[i], h[m]]; i = m; } }
            return top; };
        while (h.length) {
            const [d, u] = pop();
            if (d > dist[u]) continue;
            for (const [v, w] of g[u])
                if (d + w < dist[v]) { dist[v] = d + w; push([dist[v], v]); }
        }
        return dist;
    };
    const D1 = [], D2 = [];
    for (let i = 0; i < n; i++) { D1.push(dijkstra(g1, i)); D2.push(dijkstra(g2, i)); }
    const ans = [];
    for (let i = 0; i < n; i++) {
        let best = Infinity;
        for (let j = 0; j < n; j++)
            best = Math.min(best, D1[i][j] + prices[j] + D2[i][j]);
        ans.push(best);
    }
    return ans;
};
